    n = len(flat)

    # Count leading dominant values (same as first element) from start
    num_leading = 0
    for cell in flat:
        if cell == flat[0]:
            num_leading += 1
        else:
            break

    # Get non-leading values in order (the "others")
    others = []
    for cell in flat:
        if cell != flat[0]:
            others.append(cell)

    # Output height = n // 2 + 1
    height = n // 2 + 1

    output = []
    others_idx = 0  # Track progress through non-leading values

    for i in range(height):
        row = []
        # Build leading section
        for j in range(num_leading + i):
            row.append(flat[0])

        # Build remaining section
        remaining_width = n - len(row)
        for k in range(remaining_width):
            if others_idx < len(others):
                row.append(others[others_idx])
                others_idx += 1
            else:
                row.append(flat[0])  # Fill with dominant if no others left

        output.append(row)

    return output
